#include <stdio.h>
#include <string.h>

/* 朴素对法：每个起点都从头对一遍，答「比了几次」；所有起点都试遍了还没有就答负数 */
int naive(const char *text, const char *pat) {
    int n = (int)strlen(text);
    int m = (int)strlen(pat);
    int tries = 0;

    for (int i = 0; i + m < n; i++) {
        int j = 0;
        while (j < m) {
            tries++;
            if (text[i + j] != pat[j]) {
                break;                 /* 对不上，这个起点作废 */
            }
            j++;
        }
        if (j == m) {
            return tries;              /* 整段都对上了 */
        }
    }
    return -tries;                     /* 所有起点都试过了，没有 */
}

int main(void) {
    int a = naive("{pre}{w}", "{w}");
    if (a < 0) {
        printf("朴素对法：没找着\n");
    } else {
        printf("朴素对法比了 %d 次\n", a);
    }
    return 0;
}

